    /**
     * 通用HTTP接口，支持URL链接和请求体
     * 
     * @param targetUrl 目标URL
     * @param requestBody 请求体
     * @return ResponseEntity 响应结果
     */
    @PostMapping("/proxy")
    public ResponseEntity<?> proxyRequest(
            @RequestParam("url") String targetUrl,
            @RequestBody Map<String, Object> requestBody) {
        
        try {
            // 创建请求头
            java.net.URI uri = new java.net.URI(targetUrl);
            
            // 这里使用简单的GET请求，实际可以根据需要扩展为POST或其他方法
            ResponseEntity<String> response = restTemplate.getForEntity(targetUrl, String.class);
            
            // 返回响应结果
            Map<String, Object> result = new HashMap<>();
            result.put("success", true);
            result.put("status", response.getStatusCodeValue());
            result.put("data", response.getBody());
            result.put("message", "请求成功");
            
            return ResponseEntity.ok(result);
            
        } catch (Exception e) {
            // 返回错误信息
            Map<String, Object> errorResult = new HashMap<>();
            errorResult.put("success", false);
            errorResult.put("error", e.getMessage());
            errorResult.put("message", "请求失败");
            
            return ResponseEntity.internalServerError().body(errorResult);
        }
    }
    
    /**
     * 简单的GET接口
     * 
     * @param targetUrl 目标URL
     * @return ResponseEntity 响应结果
     */
    @GetMapping("/get")
    public ResponseEntity<?> getRequest(
            @RequestParam("url") String targetUrl) {
        
        try {
            ResponseEntity<String> response = restTemplate.getForEntity(targetUrl, String.class);
            
            Map<String, Object> result = new HashMap<>();
            result.put("success", true);
            result.put("status", response.getStatusCodeValue());
            result.put("data", response.getBody());
            result.put("message", "GET请求成功");
            
            return ResponseEntity.ok(result);
            
        } catch (Exception e) {
            Map<String, Object> errorResult = new HashMap<>();
            errorResult.put("success", false);
            errorResult.put("error", e.getMessage());
            errorResult.put("message", "GET请求失败");
            
            return ResponseEntity.internalServerError().body(errorResult);
        }
    }
    
    /**
     * 健康检查接口
     * 
     * @return 健康状态
     */
    @GetMapping("/health")
    public ResponseEntity<?> health() {
        Map<String, Object> result = new HashMap<>();
        result.put("status", "UP");
        result.put("message", "服务正常运行");
        result.put("timestamp", System.currentTimeMillis());
        
        return ResponseEntity.ok(result);
    }
